<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Privacy;use Acorn\SafetyHealthcheck\Database\Schema;final class Retention{public function cleanup():void{global$wpdb;$s=array_merge(require dirname(__DIR__,2).'/config/settings-defaults.php',get_option('acorn_hc_settings',[]));$cut=gmdate('Y-m-d H:i:s',time()-DAY_IN_SECONDS*(int)$s['incomplete_retention_days']);$ids=$wpdb->get_col($wpdb->prepare('SELECT id FROM '.Schema::table('assessments').' WHERE status=%s AND last_activity_at<%s','in_progress',$cut));foreach($ids as$id){$wpdb->delete(Schema::table('answers'),['assessment_id'=>$id]);$wpdb->delete(Schema::table('assessments'),['id'=>$id]);}}}
